// Define a simple Matrix struct to represent the return type
#[derive(Debug, PartialEq, Eq)]
pub struct Matrix<T> {
    data: Vec<Vec<T>>,
    rows: usize,
    cols: usize,
}

impl<T> Matrix<T> {
    // Helper method to create a new matrix
    fn new(data: Vec<Vec<T>>, rows: usize, cols: usize) -> Self {
        Matrix { data, rows, cols }
    }
}

fn broadcast(a: Vec<i8>, shape: Vec<u8>) -> Matrix<i8> {
    // Extract dimensions from shape
    let r = shape[0] as usize;
    let c = shape[1] as usize;
    
    // Get the length of the input array
    let len = a.len();
    
    // Create the result matrix
    let mut result = Vec::with_capacity(r);
    
    if len == r {
        // Array length equals R: treat as column vector
        // Each row i gets the i-th element repeated C times
        for i in 0..r {
            let element = a[i];
            let row = vec![element; c];
            result.push(row);
        }
    } else if len == c {
        // Array length equals C: treat as row vector
        // Each row gets the entire array
        for _ in 0..r {
            result.push(a.clone());
        }
    } else {
        // According to the problem statement, this shouldn't happen
        // because at least one dimension must match the array length
        panic!("Array length must match either R or C");
    }
    
    Matrix::new(result, r, c)
}